def subtract(a, b):
    def clean(intervals):
        return [(s, e) for s, e in intervals if s < e]

    a = clean(a)
    b = clean(b)

    if not a:
        return []

    coords = set()
    for s, e in a:
        coords.add(s)
        coords.add(e)
    for s, e in b:
        coords.add(s)
        coords.add(e)

    coords = sorted(coords)

    a_diff = {}
    b_diff = {}
    for s, e in a:
        a_diff[s] = a_diff.get(s, 0) + 1
        a_diff[e] = a_diff.get(e, 0) - 1
    for s, e in b:
        b_diff[s] = b_diff.get(s, 0) + 1
        b_diff[e] = b_diff.get(e, 0) - 1

    result = []
    a_count = 0
    b_count = 0
    cur_start = None

    for i in range(len(coords) - 1):
        pt = coords[i]
        a_count += a_diff.get(pt, 0)
        b_count += b_diff.get(pt, 0)

        covered = a_count > 0 and b_count == 0

        if covered:
            if cur_start is None:
                cur_start = pt
        else:
            if cur_start is not None:
                result.append([cur_start, pt])
                cur_start = None

    if cur_start is not None:
        result.append([cur_start, coords[-1]])

    return result

